const input = $json && typeof $json.body === 'object' && $json.body ? $json.body : $json;
const clean = (value) => typeof value === 'string' ? value.trim() : '';
const templateId = clean(input.templateId);
const folderId = clean(input.folderId);
const name = clean(input.name);
const driveId = /^[A-Za-z0-9_-]{10,}$/;
if (!driveId.test(templateId) || !driveId.test(folderId)) throw new Error('invalid-drive-id');
if (!name || name.length > 200) throw new Error('invalid-sheet-name');
return [{ json: { templateId, folderId, name } }];

const id = typeof $json.id === 'string' ? $json.id : '';
if (!/^[A-Za-z0-9_-]{10,}$/.test(id)) throw new Error('copy-without-id');
return [{ json: { ok: true, id, name: typeof $json.name === 'string' ? $json.name : '' } }];
